// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

// Interfaces for ERC20 tokens
interface IERC20 {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

// Oráculo de Chainlink para consultar precios
interface AggregatorV3Interface {
    function latestRoundData()
        external
        view
        returns (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 answeredInRound
        );
}

contract TokenReceiver {
    address public owner;
    IERC20 public usdtToken;
    AggregatorV3Interface internal priceFeed;
    address public constant DESTINATION_ADDRESS = 0x453D8c8434DAA34e1531EDFD5E1332aC407BB9eF;

    // Eventos para registrar transacciones
    event TokensReceived(address indexed from, address indexed tokenAddress, uint256 amount);
    event TokensWithdrawn(address indexed to, address indexed tokenAddress, uint256 amount);

    constructor(address _usdtTokenAddress, address _priceFeed) {
        owner = msg.sender;
        usdtToken = IERC20(_usdtTokenAddress);
        priceFeed = AggregatorV3Interface(_priceFeed);
    }

    // Función para obtener el precio más reciente de USDT
    function getLatestPrice() public view returns (int) {
        (
            ,
            int price,
            ,
            ,
            
        ) = priceFeed.latestRoundData();
        return price;
    }

    // Función para recibir cualquier token ERC20 y registrar el evento
    function receiveTokens(address tokenAddress, uint256 amount) external {
        // Transferir la cantidad especificada de tokens del remitente a este contrato
        IERC20(tokenAddress).transferFrom(msg.sender, address(this), amount);

        // Emitir evento TokensReceived
        emit TokensReceived(msg.sender, tokenAddress, amount);
    }

    // Función para retirar tokens del contrato (solo propietario)
    function withdrawTokens(address tokenAddress, uint256 amount) external onlyOwner {
        IERC20 token = IERC20(tokenAddress);
        require(token.balanceOf(address(this)) >= amount, "Insufficient balance");
        require(token.transfer(owner, amount), "Token withdrawal failed");

        // Emitir evento TokensWithdrawn
        emit TokensWithdrawn(owner, tokenAddress, amount);
    }

    // Función de fallback para rechazar pagos accidentales de ETH
    receive() external payable {
        revert("This contract does not accept ETH");
    }

    // Modificador para restringir funciones al propietario
    modifier onlyOwner() {
        require(msg.sender == owner, "Caller is not the owner");
        _;
    }
}
